125:     <p class="subtitle" id="endText"></p>
126:     <button id="nextBtn" class="primary">Siguiente nivel</button>
127:   </div>
128: </div>
129: <script>
130: const foods = [
131:   {id:'pizza',name:'Pizza',emoji:'🍕',key:'1'},
132:   {id:'tacos',name:'Tacos',emoji:'🌮',key:'2'},
133:   {id:'risotto',name:'Risotto',emoji:'🍚',key:'3'},
134:   {id:'pasta',name:'Pastas',emoji:'🍝',key:'4'},
135:   {id:'milanesa',name:'Milanesa',emoji:'🥩',key:'5'},
136:   {id:'burger',name:'Hamburguesa',emoji:'🍔',key:'6'}
137: ];
138: const $=s=>document.querySelector(s);
139: let level=1, score=0, lives=3, combo=0, goal=8, served=0;
140: let orders=[], running=false, spawnTimer=null, tickTimer=null, unlocked=+(localStorage.motricceUnlocked||1);
141: let best=+(localStorage.motricceBest||0);
142: 
143: function renderTray(){
144:   $('#tray').innerHTML=foods.map(f=>`<button class="food" data-id="${f.id}" aria-label="${f.name}"><span class="art">${f.emoji}</span><span class="key">${f.key}</span></button>`).join('');
145: }
146: function renderOrders(){
147:   $('#orders').innerHTML=orders.map((o,i)=>`<div class="order ${o.time/o.maxTime<.28?'urgent':''}" data-index="${i}"><span class="emoji">${o.food.emoji}</span><span class="name">${o.food.name}</span><div class="timer"><i style="width:${Math.max(0,o.time/o.maxTime*100)}%"></i></div></div>`).join('');
148: }
149: function startLevel(n){
150:   level=n; score=n===level?score:0; score=0; lives=3; combo=0; served=0;
151:   goal=6+level*2; orders=[]; running=true;
152:   $('#startScreen').classList.add('hidden'); $('#levelScreen').classList.add('hidden'); $('#endScreen').classList.add('hidden');
153:   $('#level').textContent=level; $('#score').textContent='0'; $('#lives').textContent='❤❤❤'; $('#progressFill').style.width='0';
154:   renderTray(); spawnOrder(); spawnOrder();
155:   clearInterval(spawnTimer); clearInterval(tickTimer);
156:   spawnTimer=setInterval(()=>{ if(running && orders.length<Math.min(3+Math.floor(level/2),5)) spawnOrder(); },Math.max(2300,5200-level*350));
157:   tickTimer=setInterval(tick,100);
158: }
159: function spawnOrder(){
160:   const pool=foods.slice(0,Math.min(4+Math.floor((level-1)/2),foods.length));
161:   const food=pool[Math.floor(Math.random()*pool.length)];
162:   const maxTime=Math.max(5000,10500-level*550);
163:   orders.push({food,time:maxTime,maxTime}); renderOrders();
164: }
165: function tick(){
166:   if(!running)return;
167:   for(let i=orders.length-1;i>=0;i--){ orders[i].time-=100; if(orders[i].time<=0){ orders.splice(i,1); loseLife(); } }
168:   renderOrders();
169: }
170: function loseLife(){
171:   lives--; combo=0; $('#lives').textContent='❤'.repeat(lives)+'♡'.repeat(3-lives); floatText('¡Perdido!',50,'#ef4028');
172:   if(lives<=0) endGame(false);
173: }
174: function serve(id){
175:   if(!running)return;
176:   const idx=orders.findIndex(o=>o.food.id===id);
177:   if(idx<0){ combo=0; lives--; $('#lives').textContent='❤'.repeat(lives)+'♡'.repeat(3-lives); floatText('Pedido incorrecto',window.innerWidth*.5,'#ef4028'); if(lives<=0)endGame(false); return; }
178:   const o=orders[idx]; orders.splice(idx,1);
179:   combo++; served++; const fast=o.time/o.maxTime>.55?200:100; const pts=(100+fast)*combo;
180:   score+=pts; $('#score').textContent=score; $('#progressFill').style.width=Math.min(100,served/goal*100)+'%';
181:   if(combo>=2){ $('#comboNum').textContent='x'+combo; $('#combo').classList.add('show'); clearTimeout($('#combo').hideT); $('#combo').hideT=setTimeout(()=>$('#combo').classList.remove('show'),900); }
182:   floatText('+'+pts,window.innerWidth*.5,'#fff');
183:   const chef=$('#chef'); chef.classList.remove('cooking'); void chef.offsetWidth; chef.classList.add('cooking'); clearTimeout(chef.cookTimer); chef.cookTimer=setTimeout(()=>chef.classList.remove('cooking'),1550);
184:   renderOrders();
185:   if(served>=goal) endGame(true);
186:   else if(orders.length<3) setTimeout(spawnOrder,180);
187: }
188: function floatText(text,x,color){
189:   const f=document.createElement('div'); f.className='floater'; f.textContent=text; f.style.left=(typeof x==='number'?x:200)+'px'; f.style.top=(window.innerHeight*.40)+'px'; f.style.color=color; $('#floaters').appendChild(f); setTimeout(()=>f.remove(),700);
190: }
191: function endGame(won){
192:   running=false; clearInterval(spawnTimer); clearInterval(tickTimer);
193:   best=Math.max(best,score); localStorage.motricceBest=best;
194:   if(won){ unlocked=Math.max(unlocked,Math.min(6,level+1)); localStorage.motricceUnlocked=unlocked; }
195:   $('#endTitle').innerHTML=won?'¡Nivel superado!':'<em>Servicio cerrado</em>';
196:   $('#endText').textContent=won?`Completaste ${served} pedidos y lograste ${score} puntos.`:`Te quedaron pedidos sin servir. Lograste ${score} puntos.`;
197:   $('#nextBtn').textContent=won?(level<6?'Siguiente nivel':'Jugar de nuevo'):'Reintentar';
198:   $('#nextBtn').onclick=()=>won?(level<6?startLevel(level+1):startLevel(1)):startLevel(level);
199:   $('#endScreen').classList.remove('hidden');
200: }
201: function showLevels(){
202:   $('#levelGrid').innerHTML='';
203:   for(let i=1;i<=6;i++){
204:     const b=document.createElement('button'); b.className='levelbtn '+(i<unlocked?'done ':'')+(i>unlocked?'locked ':''); b.textContent=i>unlocked?'🔒':i;
205:     b.onclick=()=>{if(i<=unlocked)startLevel(i)}; $('#levelGrid').appendChild(b);
206:   }
207: }
208: $('#playBtn').onclick=()=>{ showLevels(); $('#levelScreen').classList.remove('hidden'); };
209: $('#backBtn').onclick=()=>{ $('#levelScreen').classList.add('hidden'); $('#startScreen').classList.remove('hidden'); };
210: $('#tray').addEventListener('click',e=>{const b=e.target.closest('.food'); if(b)serve(b.dataset.id)});
211: window.addEventListener('keydown',e=>{const f=foods.find(x=>x.key===e.key); if(f)serve(f.id)});
212: $('#recordText').textContent='Mejor puntuación: '+best;
213: renderTray();
214: </script>
215: </body>
216: </html>

